-- Wave 6 postcheck\nselect column_name from information_schema.columns where table_schema='public' and table_name='dimensional_gate_settings' and column_name in ('activity_lookback_days','activity_event_limit') order by column_name;\nselect p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('dimensional_gate_activity_context','student_begin_dimensional_gate_chat') order by p.proname;\n